module.exports = /*#__PURE__*/JSON.parse('{"title":"What Push Chain Abstracts so You Don\'t Have to?","description":"Universal Signer lets you keep the signer you already use today — Push wraps it under the hood and eliminates all cross-chain plumbing from your app.","frontMatter":{"slug":"what-push-chain-abstracts","title":"What Push Chain Abstracts so You Don\'t Have to?","authors":["push"],"image":"./cover-image.webp","description":"Universal Signer lets you keep the signer you already use today — Push wraps it under the hood and eliminates all cross-chain plumbing from your app.","text":"Universal Signer lets you keep the signer you already use today — Push wraps it under the hood and eliminates all cross-chain plumbing from your app.","tags":["Maker Monday"]},"content":{"id":"what-push-chain-abstracts","metadata":{"permalink":"/push-chain-website/pr-preview/pr-1220/blog/what-push-chain-abstracts","source":"@site/blog/2026-01-19-what-push-chain-abstracts/index.md","title":"What Push Chain Abstracts so You Don\'t Have to?","description":"Universal Signer lets you keep the signer you already use today — Push wraps it under the hood and eliminates all cross-chain plumbing from your app.","date":"2026-01-19T00:00:00.000Z","tags":[{"inline":true,"label":"Maker Monday","permalink":"/push-chain-website/pr-preview/pr-1220/blog/tags/maker-monday"}],"readingTime":1.56,"hasTruncateMarker":true,"authors":[{"name":"Push Chain","url":"https://x.com/PushChain","page":{"permalink":"/push-chain-website/pr-preview/pr-1220/blog/authors/push"},"imageURL":"/push-chain-website/pr-preview/pr-1220/assets/blog/authors/authorpush.png","key":"push"}],"frontMatter":{"slug":"what-push-chain-abstracts","title":"What Push Chain Abstracts so You Don\'t Have to?","authors":["push"],"image":"./cover-image.webp","description":"Universal Signer lets you keep the signer you already use today — Push wraps it under the hood and eliminates all cross-chain plumbing from your app.","text":"Universal Signer lets you keep the signer you already use today — Push wraps it under the hood and eliminates all cross-chain plumbing from your app.","tags":["Maker Monday"]},"unlisted":false,"prevItem":{"title":"Introducing Push Cult 👁️⃤  -  Blood Pact for Creators","permalink":"/push-chain-website/pr-preview/pr-1220/blog/introducing-the-push-cult"},"nextItem":{"title":"How Hodl Fun Hit ~$1,000,000 Volume as a Universal Token Launchpad - Case Study","permalink":"/push-chain-website/pr-preview/pr-1220/blog/case-study-hodl-fun"}},"content":"![Cover Image of What Push Chain Abstracts so You Don\'t Have to](./cover-image.webp)\\n\\n<!--truncate-->\\n\\nPicture This:\\nYou want to build a cross-chain DeFi app accessible from Ethereum, Arbitrum and Solana.\\n\\nHere\'s what you actually have to do:\\n\\n- Integrate different wallet adapters\\n- Add new providers\\n- Tackle between different account models\\n- Look after key management and so much more\\n\\nThat\'s spending more time on plumbing the infra than building the app!\\n*The best infrastructure is always invisible.*\\n\\n**Universal Signer** makes your cross-chain infra invisible.\\n**You keep the signer you already use today** (Ethers, Viem, Solana Web3, etc.)\\nPush just *wraps* it into a Universal Signer and makes it speak \\"universal\\" under the hood.\\n\\n\\n![Universal Signer architecture diagram](./image1.webp)\\n\\n## What pain does it kill?\\n\\nWithout Universal Signer, you\'d normally:\\n\\n- Maintain different wallet flows per chain\\n- Treat Solana / EVM / L2s as separate worlds\\n- Glue bridges + RPCs + signature formats by hand\\n- Rebuild the same \\"connect → sign → send\\" logic N times\\n\\nWith Universal Signer:\\n\\n- You pass in one existing signer\\n- Push maps it to a Universal Executor Account (UEA) on Push Chain\\n- That account becomes your app\'s universal execution identity\\n- All the routing, gas, and cross-chain glue is done for you\\n\\nYou still code like it\'s a normal app.\\nAnd focus your energy where it matters the most — your app\'s features.\\n\\n## The Magic of `toUniversal()`\\n\\nWhen you call:\\n\\n```js\\nconst universalSigner = await PushChain.utils.signer.toUniversal(signer);\\n```\\n\\nThis is what happens under the hood:\\n\\n**1. Signature Scheme Detection**\\n\\nPush Chain detects:\\n- if (signer is ECDSA) → EVM chains (Ethereum, Polygon, Arbitrum, etc.)\\n- if (signer is Ed25519) → Solana, Cosmos, etc.\\n\\n**2. Chain Origin Identification**\\n\\nPush Chain reads RPC provider and determines whether the calling rpc network is Ethereum Sepolia, Solana Devnet or Push Chain itself.\\n\\n**3. And Verifies the Signature Format**\\n\\n- The user **never leaves their wallet of choice**\\n- The app **never re-implements cross-chain logic**\\n- The chain **handles all the ugly bits** (bridges, proofs, gas conversions, settlement)\\n\\nFor users the UX remains the same:\\n\\n- Use the wallet they already trust\\n- Stay on their home chain\\n- Still interact with Universal Apps running on Push Chain\\n\\n## How it fits into your app\'s flow\\n\\nThink of your flow in three layers:\\n\\n**1. Wallet / Signer** — Whatever you already use today\\n- Ethers Wallet + Provider\\n- Viem walletClient\\n- Solana Keypair\\n\\n**2. Universal Signer (Push)**\\nYou wrap that signer once:\\n*\\"Hey Push, this is my user. Make them universal.\\"*\\n\\n**3. Universal Client + Transactions**\\nNow your calls like `universal.sendTransaction(...)` automatically route from that user on that chain → Push Chain.\\n\\n## As a Developer, Here\'s What You DON\'T Write:\\n\\n❌ Chain Detection Logic\\n❌ Signature Verification\\n❌ Gas Estimation Across Chains\\n❌ Settlement Tracking\\n\\n**same signer → new superpowers.**\\n\\n*The best infrastructure is invisible. Developers shouldn\'t think about chains — they should think about apps and its features.*\\n\\nBuild Universal Apps in weeks, not months — [push.org/docs](https://push.org/docs)"},"twitterId":""}');

